package ge.tbc.config;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

/**
 * At startup, scans for the IDE's {@code mcp.json} file, finds the entry
 * whose URL matches this server, and extracts the {@code X-Conn-*} headers
 * into {@link RequestCredentials}.
 * <p>
 * This works around MCP clients (e.g. JetBrains Copilot) that configure
 * custom headers in mcp.json but do not actually send them over HTTP.
 */
@Component
public class ConnectionBootstrap {

    private static final Logger log = LoggerFactory.getLogger(ConnectionBootstrap.class);
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final String HEADER_PREFIX = "X-Conn-";

    @Value("${server.port:8081}")
    private int serverPort;

    private final RequestCredentials credentials;

    public ConnectionBootstrap(RequestCredentials credentials) {
        this.credentials = credentials;
    }

    @PostConstruct
    public void init() {
        Path mcpJson = findMcpJson();
        if (mcpJson == null) {
            log.warn("No mcp.json found — connections will only work if the MCP client sends X-Conn-* headers");
            return;
        }

        log.info("Reading connections from {}", mcpJson);

        try {
            JsonNode root = MAPPER.readTree(mcpJson.toFile());
            JsonNode servers = root.path("servers");
            if (servers.isMissingNode()) {
                servers = root.path("mcpServers");
            }

            for (Iterator<Map.Entry<String, JsonNode>> it = servers.fields(); it.hasNext(); ) {
                Map.Entry<String, JsonNode> entry = it.next();
                JsonNode serverNode = entry.getValue();

                String url = serverNode.path("url").asText("");
                if (!url.contains(":" + serverPort)) continue;

                JsonNode headers = serverNode.path("headers");
                if (headers.isMissingNode() || !headers.isObject()) continue;

                Map<String, DbEnvironment> parsed = new LinkedHashMap<>();
                for (Iterator<Map.Entry<String, JsonNode>> hIt = headers.fields(); hIt.hasNext(); ) {
                    Map.Entry<String, JsonNode> h = hIt.next();
                    String headerName = h.getKey();
                    if (!headerName.startsWith(HEADER_PREFIX)) continue;

                    String envName = headerName.substring(HEADER_PREFIX.length());
                    String json = h.getValue().asText();
                    try {
                        DbEnvironment env = MAPPER.readValue(json, DbEnvironment.class);
                        env.setName(envName);
                        parsed.put(envName, env);
                    } catch (Exception e) {
                        log.warn("Failed to parse {} from mcp.json: {}", headerName, e.getMessage());
                    }
                }

                if (!parsed.isEmpty()) {
                    credentials.setAll(parsed);
                    log.info("Loaded {} connection(s) from mcp.json [{}]: {}",
                            parsed.size(), entry.getKey(), parsed.keySet());
                }
                return;
            }

            log.warn("No server entry in {} matches port {}", mcpJson, serverPort);

        } catch (IOException e) {
            log.error("Failed to read {}: {}", mcpJson, e.getMessage());
        }
    }

    private Path findMcpJson() {
        Path cwd = Path.of("").toAbsolutePath();
        Path candidate = cwd.resolve("mcp.json");
        if (Files.isRegularFile(candidate)) return candidate;

        Path dir = cwd;
        while (dir != null) {
            candidate = dir.resolve(".github").resolve("copilot").resolve("mcp.json");
            if (Files.isRegularFile(candidate)) return candidate;
            dir = dir.getParent();
        }

        String home = System.getProperty("user.home");
        if (home != null) {
            candidate = Path.of(home, ".config", "github-copilot", "mcp.json");
            if (Files.isRegularFile(candidate)) return candidate;
            String appData = System.getenv("APPDATA");
            if (appData != null) {
                candidate = Path.of(appData, "GitHub Copilot", "mcp.json");
                if (Files.isRegularFile(candidate)) return candidate;
            }
        }

        return null;
    }
}

package ge.tbc.config;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;

